mapper.select:
select * from ( select t.*, (case when t.allocation_source = 'MANUAL' then '手工分配' else '自动匹配' end)as allocation_source_desc, (case when t.allocation_status = 'Y' then '是' else '否' end)as allocation_status_desc, (select sum(ct.transaction_amount) from csh_transaction ct,csh_allocation_receipt car where car.allocation_id=t.allocation_id and car.transaction_id = ct.transaction_id)as total_amount, (select wm_concat(bp.bp_name) from CSH_TRANSACTION ct ,csh_allocation_receipt car ,hls_bp_master bp where car.allocation_id=t.allocation_id and car.transaction_id = ct.transaction_id and ct.bp_id = bp.bp_id)as bp_name, (select wm_concat(ct.transaction_num) from CSH_TRANSACTION ct ,csh_allocation_receipt car where car.allocation_id=t.allocation_id and car.transaction_id = ct.transaction_id)as transaction_num, (select u.description from sys_user u where u.user_id = t.created_by) as created_by_name, (select sum(ct.transaction_amount)-sum(ct.write_off_amount) from csh_transaction ct,csh_allocation_receipt car where car.transaction_id = ct.transaction_id and car.allocation_id = t.allocation_id)as un_write_off_amount, (select sum(cc.due_amount)-sum(cc.received_amount) from con_contract_cashflow cc,csh_allocation_credit cac where cc.cashflow_id = cac.cashflow_id and cac.allocation_id = t.allocation_id)as can_write_off_amount from csh_allocation t) t1
1=1
and t1.allocation_number like #{allocationNumber}
and t1.transaction_num like #{transactionNum}
and t1.allocation_id in
#{item}
and t1.allocation_id = #{allocationId}
order by t1.allocation_number desc
